// M9: structured x86-64 decoder tests (byte-exact expectations).
//
// Every expectation below was derived from the Intel SDM opcode tables /
// ModRM+SIB encoding rules by hand; none is generated by the decoder.

#include <cstdint>
#include <cstdio>
#include <initializer_list>
#include <set>
#include <string>
#include <utility>
#include <vector>

#include <gtest/gtest.h>

#include "xbox2pc/x64_decoder.hpp"

namespace x64 = xbox2pc::rt::x64;

namespace {

std::string hex(const std::vector<std::uint8_t>& v) {
    std::string s;
    char buf[8];
    for (auto b : v) {
        std::snprintf(buf, sizeof buf, "%02X ", b);
        s += buf;
    }
    return s;
}

std::vector<std::uint8_t> bytes(std::initializer_list<int> list) {
    std::vector<std::uint8_t> v;
    for (int b : list) v.push_back(static_cast<std::uint8_t>(b));
    return v;
}

constexpr std::uint64_t kRip = 0x1000;

x64::Decoded ok(std::initializer_list<int> list, std::uint64_t rip = kRip) {
    const auto v = bytes(list);
    const auto r = x64::decode(v.data(), v.size(), rip);
    if (r.status != x64::DecodeStatus::Ok) {
        ADD_FAILURE() << "expected Ok for [" << hex(v) << "] got "
                      << x64::status_name(r.status) << " (" << r.reason << ")";
        return x64::Decoded{};
    }
    if (r.ins.length != v.size()) {
        ADD_FAILURE() << "length mismatch for [" << hex(v) << "]: decoder consumed "
                      << static_cast<int>(r.ins.length);
    }
    if (r.consumed != r.ins.length) {
        ADD_FAILURE() << "consumed != length for [" << hex(v) << "]";
    }
    return r.ins;
}

x64::DecodeResult bad(std::initializer_list<int> list, x64::DecodeStatus want,
                      x64::RejectClass cls) {
    const auto v = bytes(list);
    const auto r = x64::decode(v.data(), v.size(), kRip);
    if (r.status != want || r.reject != cls) {
        ADD_FAILURE() << "expected " << x64::status_name(want) << "/"
                      << x64::reject_class_name(cls) << " for [" << hex(v) << "] got "
                      << x64::status_name(r.status) << "/"
                      << x64::reject_class_name(r.reject) << " (" << r.reason << ")";
    }
    if (want != x64::DecodeStatus::Ok && (r.reason == nullptr || r.reason[0] == '\0')) {
        ADD_FAILURE() << "reject without a reason for [" << hex(v) << "]";
    }
    return r;
}

constexpr std::uint32_t kAll6 = x64::kRfCf | x64::kRfPf | x64::kRfAf | x64::kRfZf |
                                x64::kRfSf | x64::kRfOf;

}  // namespace

// ── prefixes + REX ────────────────────────────────────────────────────────

TEST(X64Decoder, PrefixAndRexBasics) {
    const auto d = ok({0x48, 0xB8, 1, 2, 3, 4, 5, 6, 7, 8});
    EXPECT_EQ(d.mnem, x64::Mnemonic::Mov);
    EXPECT_EQ(d.length, 10);
    EXPECT_EQ(d.rex, 0x48);
    EXPECT_EQ(d.op_size, 64);
    ASSERT_EQ(d.op_count, 2);
    EXPECT_EQ(d.ops[0].kind, x64::OpKind::Reg);
    EXPECT_EQ(d.ops[0].bits, 64);
    EXPECT_EQ(d.ops[0].reg, 0);
    EXPECT_EQ(d.ops[1].kind, x64::OpKind::Imm);
    EXPECT_EQ(d.ops[1].imm_bits, 64);
    EXPECT_EQ(d.ops[1].imm, 0x0807060504030201ull);
}

TEST(X64Decoder, RexDroppedByLaterLegacyPrefix) {
    // 48 66 89 C8: the REX is not the last prefix -> ignored -> mov ax, cx.
    const auto d = ok({0x48, 0x66, 0x89, 0xC8});
    EXPECT_EQ(d.rex, 0);
    EXPECT_EQ(d.op_size, 16);
    EXPECT_EQ(x64::format_instruction(d), "mov ax, cx");
}

TEST(X64Decoder, LastRexWins) {
    // 48 40 89 C8: the last REX (0x40, no W) applies.
    const auto a = ok({0x48, 0x40, 0x89, 0xC8});
    EXPECT_EQ(a.rex, 0x40);
    EXPECT_EQ(a.op_size, 32);
    EXPECT_EQ(x64::format_instruction(a), "mov eax, ecx");
    // 40 48 89 C8: the last REX (0x48) applies.
    const auto b = ok({0x40, 0x48, 0x89, 0xC8});
    EXPECT_EQ(b.rex, 0x48);
    EXPECT_EQ(b.op_size, 64);
    EXPECT_EQ(x64::format_instruction(b), "mov rax, rcx");
}

TEST(X64Decoder, OperandSizes) {
    EXPECT_EQ(ok({0x89, 0xC8}).op_size, 32);           // mov eax, ecx
    EXPECT_EQ(ok({0x66, 0x89, 0xC8}).op_size, 16);     // mov ax, cx
    EXPECT_EQ(ok({0x48, 0x89, 0xC8}).op_size, 64);     // mov rax, rcx
    // 66 with REX.W: 66 is ignored.
    EXPECT_EQ(ok({0x66, 0x48, 0x89, 0xC8}).op_size, 64);
    EXPECT_EQ(ok({0x88, 0xC8}).ops[0].bits, 8);        // mov al, cl
}

TEST(X64Decoder, ByteRegistersFollowTheRexRule) {
    EXPECT_EQ(x64::format_instruction(ok({0x88, 0xE5})), "mov ch, ah");
    EXPECT_EQ(x64::format_instruction(ok({0x40, 0x88, 0xE5})), "mov bpl, spl");
    EXPECT_EQ(x64::format_instruction(ok({0x41, 0x88, 0xC4})), "mov r12b, al");
    EXPECT_EQ(x64::format_instruction(ok({0x8A, 0xC8})), "mov cl, al");
    EXPECT_EQ(x64::register_name(4, 8, false), "ah");
    EXPECT_EQ(x64::register_name(4, 8, true), "spl");
    EXPECT_EQ(x64::register_name(12, 16, true), "r12w");
    EXPECT_EQ(x64::register_name(15, 32, true), "r15d");
}

// ── addressing modes ──────────────────────────────────────────────────────

TEST(X64Decoder, AddressingModes) {
    {   // [rax]
        const auto d = ok({0x48, 0x8B, 0x00});
        ASSERT_EQ(d.op_count, 2);
        EXPECT_EQ(d.ops[1].kind, x64::OpKind::Mem);
        EXPECT_EQ(d.ops[1].base, 0);
        EXPECT_EQ(d.ops[1].index, x64::kNoReg);
        EXPECT_EQ(d.ops[1].disp, 0);
        EXPECT_EQ(d.ops[1].seg, x64::Segment::None);
    }
    {   // [rbp-8]
        const auto d = ok({0x48, 0x8B, 0x45, 0xF8});
        EXPECT_EQ(d.ops[1].base, 5);
        EXPECT_EQ(d.ops[1].disp, -8);
        EXPECT_EQ(d.length, 4);
        EXPECT_EQ(x64::format_instruction(d), "mov rax, qword ptr [rbp - 0x8]");
    }
    {   // [rbp+0x100]
        const auto d = ok({0x48, 0x8B, 0x85, 0x00, 0x01, 0x00, 0x00});
        EXPECT_EQ(d.ops[1].base, 5);
        EXPECT_EQ(d.ops[1].disp, 0x100);
        EXPECT_EQ(d.length, 7);
    }
    {   // [rax+rcx*1+0x10]
        const auto d = ok({0x48, 0x8B, 0x44, 0x08, 0x10});
        EXPECT_EQ(d.ops[1].base, 0);
        EXPECT_EQ(d.ops[1].index, 1);
        EXPECT_EQ(d.ops[1].scale, 1);
        EXPECT_EQ(d.ops[1].disp, 0x10);
    }
    {   // [rax*8+0x1000] (SIB base=101, mod=0: no base, disp32)
        const auto d = ok({0x48, 0x8B, 0x04, 0xC5, 0x00, 0x10, 0x00, 0x00});
        EXPECT_EQ(d.ops[1].base, x64::kNoReg);
        EXPECT_EQ(d.ops[1].index, 0);
        EXPECT_EQ(d.ops[1].scale, 8);
        EXPECT_EQ(d.ops[1].disp, 0x1000);
        EXPECT_EQ(x64::format_instruction(d), "mov rax, qword ptr [rax*8 + 0x1000]");
    }
    {   // [rsp-0x18] (SIB index=100: no index)
        const auto d = ok({0x48, 0x8B, 0x44, 0x24, 0xE8});
        EXPECT_EQ(d.ops[1].base, 4);
        EXPECT_EQ(d.ops[1].index, x64::kNoReg);
        EXPECT_EQ(d.ops[1].disp, -0x18);
    }
    {   // [rip+0x10]
        const auto d = ok({0x48, 0x8B, 0x05, 0x10, 0x00, 0x00, 0x00}, kRip);
        EXPECT_TRUE(d.ops[1].rip_relative);
        EXPECT_EQ(d.ops[1].base, x64::kNoReg);
        EXPECT_EQ(d.ops[1].disp, 0x10);
        EXPECT_EQ(x64::format_instruction(d), "mov rax, qword ptr [rip + 0x10]");
    }
    {   // [r8+r9+0x10]: REX.WRXB = 0x4F
        const auto d = ok({0x4F, 0x8B, 0x44, 0x08, 0x10});
        EXPECT_EQ(d.ops[0].reg, 8);
        EXPECT_EQ(d.ops[1].base, 8);
        EXPECT_EQ(d.ops[1].index, 9);
        EXPECT_EQ(x64::format_instruction(d), "mov r8, qword ptr [r8 + r9 + 0x10]");
    }
    {   // REX 0x4D has X=0: the index stays rcx
        const auto d = ok({0x4D, 0x8B, 0x44, 0x08, 0x10});
        EXPECT_EQ(d.ops[1].base, 8);
        EXPECT_EQ(d.ops[1].index, 1);
    }
    {   // [r12] needs a SIB byte with the no-index pattern
        const auto d = ok({0x49, 0x8B, 0x04, 0x24});
        EXPECT_EQ(d.ops[1].base, 12);
        EXPECT_EQ(d.ops[1].index, x64::kNoReg);
    }
    {   // [r13] needs disp8=0
        const auto d = ok({0x49, 0x8B, 0x45, 0x00});
        EXPECT_EQ(d.ops[1].base, 13);
        EXPECT_EQ(d.ops[1].disp, 0);
    }
    {   // [r12*8+0x1000] with REX.X = 0x42
        const auto d = ok({0x42, 0x8B, 0x04, 0xE5, 0x00, 0x10, 0x00, 0x00});
        EXPECT_EQ(d.ops[1].base, x64::kNoReg);
        EXPECT_EQ(d.ops[1].index, 12);
        EXPECT_EQ(d.ops[1].scale, 8);
        EXPECT_EQ(d.ops[1].disp, 0x1000);
    }
    {   // [rcx+rdx*4-0x20]
        const auto d = ok({0x48, 0x8B, 0x44, 0x91, 0xE0});
        EXPECT_EQ(d.ops[1].base, 1);
        EXPECT_EQ(d.ops[1].index, 2);
        EXPECT_EQ(d.ops[1].scale, 4);
        EXPECT_EQ(d.ops[1].disp, -0x20);
        EXPECT_EQ(x64::format_instruction(d), "mov rax, qword ptr [rcx + rdx*4 - 0x20]");
    }
}

TEST(X64Decoder, SegmentAndAddressSizePrefixes) {
    {   // gs:[0x58]
        const auto d = ok({0x65, 0x48, 0x8B, 0x04, 0x25, 0x58, 0x00, 0x00, 0x00});
        EXPECT_EQ(d.ops[1].seg, x64::Segment::Gs);
        EXPECT_EQ(d.ops[1].base, x64::kNoReg);
        EXPECT_EQ(d.ops[1].disp, 0x58);
        EXPECT_EQ(x64::format_instruction(d), "mov rax, qword ptr gs:[0x58]");
    }
    EXPECT_EQ(ok({0x64, 0x48, 0x8B, 0x04, 0x25, 0x00, 0x00, 0x00, 0x00}).ops[1].seg,
              x64::Segment::Fs);
    EXPECT_EQ(ok({0x36, 0x48, 0x8B, 0x45, 0x00}).ops[1].seg, x64::Segment::Ss);
    EXPECT_EQ(x64::format_instruction(ok({0x2E, 0x90})), "nop");
    {   // 67: 32-bit address size, absolute [0x1000]
        const auto d = ok({0x67, 0x48, 0x8B, 0x04, 0x25, 0x00, 0x10, 0x00, 0x00});
        EXPECT_EQ(d.addr_size, 32);
        EXPECT_TRUE(d.ops[1].addr32);
        EXPECT_EQ(x64::format_instruction(d), "mov rax, qword ptr [0x1000]");
    }
    {   // 67 with a base register: the base is read as a 32-bit register.
        const auto d = ok({0x67, 0x48, 0x8B, 0x42, 0x08});
        EXPECT_EQ(d.addr_size, 32);
        EXPECT_EQ(x64::format_instruction(d), "mov rax, qword ptr [edx + 0x8]");
    }
}

// ── data movement ─────────────────────────────────────────────────────────

TEST(X64Decoder, MovForms) {
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x89, 0xC8})), "mov rax, rcx");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x8B, 0xC8})), "mov rcx, rax");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x89, 0x08})), "mov qword ptr [rax], rcx");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x8B, 0x08})), "mov rcx, qword ptr [rax]");
    EXPECT_EQ(x64::format_instruction(ok({0x88, 0xC8})), "mov al, cl");
    EXPECT_EQ(x64::format_instruction(ok({0x66, 0x89, 0xC8})), "mov ax, cx");
    EXPECT_EQ(x64::format_instruction(ok({0xB0, 0x7F})), "mov al, 0x7f");
    EXPECT_EQ(x64::format_instruction(ok({0x41, 0xB3, 0x7F})), "mov r11b, 0x7f");
    {
        const auto d = ok({0xB8, 0x78, 0x56, 0x34, 0x12});
        EXPECT_EQ(d.op_count, 2);
        EXPECT_EQ(d.ops[1].imm, 0x12345678u);
        EXPECT_EQ(d.ops[1].imm_bits, 32);
    }
    EXPECT_EQ(ok({0x66, 0xB8, 0x78, 0x56}).ops[1].imm_bits, 16);
    EXPECT_EQ(ok({0x49, 0xBF, 1, 2, 3, 4, 5, 6, 7, 8}).ops[0].reg, 15);
    EXPECT_EQ(ok({0x41, 0xBF, 1, 2, 3, 4}).ops[0].reg, 15);            // mov r15d, imm32
    EXPECT_EQ(ok({0x41, 0xBF, 1, 2, 3, 4}).length, 6);
    EXPECT_EQ(ok({0x48, 0xB8, 1, 0, 0, 0, 0, 0, 0, 0}).ops[0].reg, 0);
    EXPECT_EQ(ok({0x49, 0xB8, 1, 0, 0, 0, 0, 0, 0, 0}).ops[0].reg, 8);
    // MOV r/m, imm
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0xC7, 0xC0, 0xFF, 0xFF, 0xFF, 0xFF})),
              "mov rax, 0xffffffff");
    EXPECT_EQ(x64::format_instruction(ok({0xC6, 0x00, 0x41})), "mov byte ptr [rax], 0x41");
    EXPECT_EQ(x64::format_instruction(ok({0x66, 0xC7, 0x00, 0x41, 0x42})),
              "mov word ptr [rax], 0x4241");
}

TEST(X64Decoder, MoffsForms) {
    {
        const auto d = ok({0x48, 0xA1, 0x00, 0x10, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00});
        EXPECT_EQ(d.mnem, x64::Mnemonic::Mov);
        ASSERT_EQ(d.op_count, 2);
        EXPECT_EQ(d.ops[1].kind, x64::OpKind::Mem);
        EXPECT_EQ(d.ops[1].base, x64::kNoReg);
        EXPECT_EQ(d.ops[1].disp, 0x100001000ll);
        EXPECT_EQ(d.length, 10);
    }
    EXPECT_EQ(x64::format_instruction(ok({0xA0, 0x78, 0x56, 0x34, 0x12, 0, 0, 0, 0})),
              "mov al, byte ptr [0x12345678]");
    bad({0xA0, 0x78, 0x56, 0x34, 0x12}, x64::DecodeStatus::Truncated,
         x64::RejectClass::NeedMoreBytes);   // moffs64 needs 8 bytes
    EXPECT_EQ(x64::format_instruction(ok({0x67, 0x48, 0xA3, 0x00, 0x10, 0x00, 0x00})),
              "mov qword ptr [0x1000], rax");
    EXPECT_EQ(ok({0x48, 0xA1, 0x00, 0x10, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}).ops[1].bits,
              64);
}

TEST(X64Decoder, MovzxMovsxMovsxd) {
    EXPECT_EQ(x64::format_instruction(ok({0x0F, 0xB6, 0xC0})), "movzx eax, al");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x0F, 0xB6, 0xC0})), "movzx rax, al");
    EXPECT_EQ(x64::format_instruction(ok({0x0F, 0xB7, 0xC0})), "movzx eax, ax");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x0F, 0xB7, 0xC0})), "movzx rax, ax");
    EXPECT_EQ(x64::format_instruction(ok({0x66, 0x0F, 0xB6, 0xC0})), "movzx ax, al");
    EXPECT_EQ(x64::format_instruction(ok({0x0F, 0xBE, 0xC0})), "movsx eax, al");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x0F, 0xBE, 0x00})),
              "movsx rax, byte ptr [rax]");
    EXPECT_EQ(x64::format_instruction(ok({0x0F, 0xBF, 0xC0})), "movsx eax, ax");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x63, 0xC0})), "movsxd rax, eax");
    bad({0x63, 0xC0}, x64::DecodeStatus::Invalid, x64::RejectClass::BadOpcode);
    bad({0x66, 0x0F, 0xB7, 0xC0}, x64::DecodeStatus::Invalid, x64::RejectClass::BadOperandSize);
    bad({0x66, 0x0F, 0xBF, 0xC0}, x64::DecodeStatus::Invalid, x64::RejectClass::BadOperandSize);
}

TEST(X64Decoder, Lea) {
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x8D, 0x04, 0x08})), "lea rax, [rax + rcx]");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x8D, 0x05, 0x00, 0x01, 0x00, 0x00})),
              "lea rax, [rip + 0x100]");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x8D, 0x84, 0x89, 0x10, 0x00, 0x00, 0x00})),
              "lea rax, [rcx + rcx*4 + 0x10]");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x8D, 0x04, 0x8D, 0x10, 0x00, 0x00, 0x00})),
              "lea rax, [rcx*4 + 0x10]");       // SIB base=101 with mod=0: no base
    EXPECT_EQ(ok({0x8D, 0x04, 0x08}).op_size, 32);
    bad({0x48, 0x8D, 0xC0}, x64::DecodeStatus::Invalid, x64::RejectClass::BadModRm);
    bad({0x66, 0x8D, 0x00}, x64::DecodeStatus::Invalid, x64::RejectClass::BadOperandSize);
}

TEST(X64Decoder, XchgAndNop) {
    EXPECT_EQ(x64::format_instruction(ok({0x91})), "xchg eax, ecx");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x91})), "xchg rax, rcx");
    // 41 90 is XCHG r8, rax — never a NOP (M8 treated it as one).
    const auto d = ok({0x41, 0x90});
    EXPECT_EQ(d.mnem, x64::Mnemonic::Xchg);
    EXPECT_EQ(d.ops[0].reg, 0);
    EXPECT_EQ(d.ops[1].reg, 8);
    EXPECT_EQ(x64::format_instruction(d), "xchg eax, r8d");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x87, 0xC8})), "xchg rax, rcx");
    EXPECT_EQ(x64::format_instruction(ok({0x87, 0x08})), "xchg dword ptr [rax], ecx");
    EXPECT_EQ(ok({0x90}).mnem, x64::Mnemonic::Xchg);
    EXPECT_EQ(x64::format_instruction(ok({0x90})), "nop");
    EXPECT_EQ(x64::format_instruction(ok({0x66, 0x90})), "nop");
    EXPECT_EQ(ok({0xF3, 0x90}).mnem, x64::Mnemonic::Nop);   // PAUSE
}

TEST(X64Decoder, HintNopsAndEndbr) {
    EXPECT_EQ(ok({0x0F, 0x1F, 0x00}).length, 3);
    EXPECT_EQ(ok({0x66, 0x0F, 0x1F, 0x84, 0x24, 0x00, 0x00, 0x00, 0x00}).length, 9);
    EXPECT_EQ(ok({0x0F, 0x1F, 0x84, 0x24, 0x00, 0x00, 0x00, 0x00}).length, 8);
    EXPECT_EQ(ok({0x0F, 0x1F, 0x80, 0x00, 0x00, 0x00, 0x00}).length, 7);
    bad({0x0F, 0x1F, 0x84, 0x00, 0x00, 0x00, 0x00}, x64::DecodeStatus::Truncated,
         x64::RejectClass::NeedMoreBytes);   // SIB byte missing
    EXPECT_EQ(ok({0x0F, 0x18, 0x00}).op_count, 0);          // prefetch hint
    const auto e = ok({0xF3, 0x0F, 0x1E, 0xFA});
    EXPECT_TRUE(e.is_endbr);
    EXPECT_EQ(e.mnem, x64::Mnemonic::Nop);
    EXPECT_EQ(x64::format_instruction(e), "endbr64");
    EXPECT_EQ(x64::format_instruction(ok({0xF3, 0x0F, 0x1E, 0xFB})), "endbr32");
}

TEST(X64Decoder, ConversionsAndBswap) {
    EXPECT_EQ(x64::format_instruction(ok({0x98})), "cwde");
    EXPECT_EQ(x64::format_instruction(ok({0x66, 0x98})), "cbw");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x98})), "cdqe");
    EXPECT_EQ(x64::format_instruction(ok({0x99})), "cdq");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x99})), "cqo");
    EXPECT_EQ(x64::format_instruction(ok({0x0F, 0xC8})), "bswap eax");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x0F, 0xC8})), "bswap rax");
    EXPECT_EQ(x64::format_instruction(ok({0x41, 0x0F, 0xC8})), "bswap r8d");
    bad({0x66, 0x0F, 0xC8}, x64::DecodeStatus::Invalid, x64::RejectClass::BadOperandSize);
}

// ── arithmetic / logic ────────────────────────────────────────────────────

TEST(X64Decoder, AluTwoOperandForms) {
    struct Form { int op; x64::Mnemonic m; const char* text; };
    const Form forms[] = {
        {0x00, x64::Mnemonic::Add, "add al, cl"},
        {0x08, x64::Mnemonic::Or, "or al, cl"},
        {0x10, x64::Mnemonic::Adc, "adc al, cl"},
        {0x18, x64::Mnemonic::Sbb, "sbb al, cl"},
        {0x20, x64::Mnemonic::And, "and al, cl"},
        {0x28, x64::Mnemonic::Sub, "sub al, cl"},
        {0x30, x64::Mnemonic::Xor, "xor al, cl"},
        {0x38, x64::Mnemonic::Cmp, "cmp al, cl"},
    };
    for (const auto& f : forms) {
        const auto a = ok({f.op, 0xC8});              // Eb, Gb  (r/m=al, reg=cl)
        EXPECT_EQ(a.mnem, f.m) << std::hex << f.op;
        EXPECT_EQ(a.op_count, 2);
        EXPECT_EQ(a.ops[0].bits, 8);
        const auto b = ok({f.op + 1, 0xC8});          // Ev, Gv
        EXPECT_EQ(b.mnem, f.m);
        EXPECT_EQ(b.ops[0].bits, 32);
        const auto c = ok({f.op + 2, 0xC8});          // Gb, Eb
        EXPECT_EQ(c.ops[0].kind, x64::OpKind::Reg);
        EXPECT_EQ(c.ops[1].kind, x64::OpKind::Reg);
        EXPECT_EQ(c.ops[0].bits, 8);
        const auto d = ok({0x48, f.op + 3, 0x08});    // Gv, Ev (memory)
        EXPECT_EQ(d.mnem, f.m);
        EXPECT_EQ(d.ops[1].kind, x64::OpKind::Mem);
        EXPECT_EQ(d.ops[1].bits, 64);
        const auto e = ok({f.op + 4, 0x7F});          // AL, imm8
        EXPECT_EQ(e.op_count, 2);
        EXPECT_EQ(e.ops[0].reg, 0);
        EXPECT_EQ(e.ops[0].bits, 8);
        EXPECT_EQ(e.ops[1].imm, 0x7Fu);
        const auto g = ok({f.op + 5, 0x78, 0x56, 0x34, 0x12});   // eAX, imm32
        EXPECT_EQ(g.ops[0].bits, 32);
        EXPECT_EQ(g.ops[1].imm_bits, 32);
    }
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x01, 0xC0})), "add rax, rax");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x29, 0xC0})), "sub rax, rax");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x31, 0xC0})), "xor rax, rax");
    EXPECT_EQ(x64::format_instruction(ok({0x48, 0x39, 0xC0})), "cmp rax, rax");
}

