// ── control flow ──────────────────────────────────────────────────────────

TEST(X64Decoder, RelativeBranches) {
    {
        const auto d = ok({0xEB, 0x10});
        EXPECT_EQ(d.mnem, x64::Mnemonic::Jmp);
        ASSERT_EQ(d.op_count, 1);
        EXPECT_EQ(d.ops[0].kind, x64::OpKind::Rel);
        EXPECT_EQ(d.ops[0].imm, 0x10u);
        EXPECT_EQ(x64::format_instruction(d), "jmp 0x1012");
    }
    EXPECT_EQ(x64::format_instruction(ok({0xEB, 0xF0})), "jmp 0xff2");
    EXPECT_EQ(x64::format_instruction(ok({0xE9, 0xFF, 0xFF, 0xFF, 0xFF})), "jmp 0x1004");
    EXPECT_EQ(ok({0xE8, 0x00, 0x01, 0x00, 0x00}).mnem, x64::Mnemonic::Call);
    EXPECT_EQ(x64::format_instruction(ok({0xE8, 0x00, 0x01, 0x00, 0x00})), "call 0x1105");
    EXPECT_EQ(x64::branch_target(ok({0xEB, 0xF0})), 0xFF2u);
    EXPECT_EQ(x64::branch_target(ok({0xE9, 0xFF, 0xFF, 0xFF, 0xFF})), 0x1004u);
    EXPECT_EQ(x64::branch_target(ok({0x0F, 0x84, 0x00, 0x01, 0x00, 0x00})), 0x1106u);
    EXPECT_EQ(x64::format_instruction(ok({0x74, 0x05})), "je 0x1007");
    EXPECT_EQ(x64::format_instruction(ok({0x75, 0x04})), "jne 0x1006");
    EXPECT_EQ(x64::format_instruction(ok({0x7C, 0x03})), "jl 0x1005");
    EXPECT_EQ(x64::format_instruction(ok({0x0F, 0x84, 0x00, 0x01, 0x00, 0x00})),
              "je 0x1106");
    EXPECT_EQ(ok({0x0F, 0x8C, 0x00, 0x01, 0x00, 0x00}).cc, 0xCu);
    EXPECT_EQ(ok({0x7C, 0x03}).cc, 0xCu);
    // every condition code decodes on both forms
    for (int cc = 0; cc < 16; ++cc) {
        const auto s = ok({0x70 + cc, 0x00});
        EXPECT_EQ(s.mnem, x64::Mnemonic::Jcc);
        EXPECT_EQ(static_cast<int>(s.cc), cc);
        const auto l = ok({0x0F, 0x80 + cc, 0, 0, 0, 0});
        EXPECT_EQ(static_cast<int>(l.cc), cc);
        EXPECT_EQ(l.length, 6);
    }
}

TEST(X64Decoder, IndirectBranches) {
    EXPECT_EQ(x64::format_instruction(ok({0xFF, 0xD0})), "call rax");
    EXPECT_EQ(x64::format_instruction(ok({0x41, 0xFF, 0xD0})), "call r8");
    EXPECT_EQ(x64::format_instruction(ok({0xFF, 0x10})), "call qword ptr [rax]");
    EXPECT_EQ(x64::format_instruction(ok({0xFF, 0xE0})), "jmp rax");
    EXPECT_EQ(x64::format_instruction(ok({0xFF, 0x24, 0x24})), "jmp qword ptr [rsp]");
    bad({0xFF, 0x1D, 0, 0, 0, 0}, x64::DecodeStatus::Unsupported,
         x64::RejectClass::UnsupportedValid);   // FF /3 far call
    bad({0xFF, 0x2D, 0, 0, 0, 0}, x64::DecodeStatus::Unsupported,
         x64::RejectClass::UnsupportedValid);   // FF /5 far jmp
    bad({0x66, 0xFF, 0xD0}, x64::DecodeStatus::Unsupported,
         x64::RejectClass::UnsupportedValid);   // 66 near call: not interpreted
    EXPECT_EQ(ok({0xFF, 0xD0}).ops[0].bits, 64u);   // near call is always 64-bit
    bad({0xFF, 0xF8}, x64::DecodeStatus::Invalid, x64::RejectClass::BadModRm);   // FF /7
}

