TEST(X64Decoder, UnsupportedClassesAreTyped) {
    using S = x64::DecodeStatus;
    using R = x64::RejectClass;
    // three-byte maps, VEX, EVEX
    bad({0x66, 0x0F, 0x38, 0x00, 0xC0}, S::Unsupported, R::UnsupportedMap);
    bad({0x66, 0x0F, 0x3A, 0x0F, 0xC0, 0x01}, S::Unsupported, R::UnsupportedMap);
    bad({0xC5, 0xF8, 0x57, 0xC0}, S::Unsupported, R::UnsupportedMap);
    bad({0xC4, 0xE2, 0x7D, 0x18, 0xC0}, S::Unsupported, R::UnsupportedMap);
    bad({0x62, 0xF1, 0x7C, 0x48, 0x28, 0xC0}, S::Unsupported, R::UnsupportedMap);
    // SSE / MMX / x87
    bad({0x0F, 0x28, 0x00}, S::Unsupported, R::UnsupportedSimd);
    bad({0x66, 0x0F, 0xEF, 0xC0}, S::Unsupported, R::UnsupportedSimd);
    bad({0xF2, 0x0F, 0x10, 0x00}, S::Unsupported, R::UnsupportedSimd);
    bad({0x66, 0x0F, 0x6E, 0xC0}, S::Unsupported, R::UnsupportedSimd);
    bad({0xD8, 0x00}, S::Unsupported, R::UnsupportedSimd);
    bad({0x0F, 0x0E}, S::Unsupported, R::UnsupportedSimd);
    // string
    bad({0xA4}, S::Unsupported, R::UnsupportedString);
    bad({0xF3, 0xA4}, S::Unsupported, R::UnsupportedString);
    bad({0xF3, 0xAB}, S::Unsupported, R::UnsupportedString);
    bad({0x6C}, S::Unsupported, R::UnsupportedString);
    // atomics
    bad({0xF0, 0x48, 0x01, 0x01}, S::Unsupported, R::UnsupportedAtomic);
    bad({0xF0, 0xFF, 0x00}, S::Unsupported, R::UnsupportedAtomic);
    bad({0xF0, 0xFE, 0x00}, S::Unsupported, R::UnsupportedAtomic);
    bad({0x0F, 0xB0, 0x00}, S::Unsupported, R::UnsupportedAtomic);
    bad({0x0F, 0xC1, 0x00}, S::Unsupported, R::UnsupportedAtomic);
    bad({0x0F, 0xC7, 0x08}, S::Unsupported, R::UnsupportedAtomic);
    bad({0xF0, 0x48, 0x0F, 0xB1, 0x01}, S::Unsupported, R::UnsupportedAtomic);
    // privileged
    bad({0xE4, 0x20}, S::Unsupported, R::UnsupportedPrivileged);
    bad({0xF4}, S::Unsupported, R::UnsupportedPrivileged);
    bad({0x0F, 0x31}, S::Unsupported, R::UnsupportedPrivileged);
    bad({0x0F, 0x05}, S::Unsupported, R::UnsupportedPrivileged);
    bad({0xFA}, S::Unsupported, R::UnsupportedPrivileged);
    bad({0xCF}, S::Unsupported, R::UnsupportedPrivileged);
    // valid but not interpreted
    bad({0x0F, 0xA2}, S::Unsupported, R::UnsupportedValid);
    bad({0xC8, 0x00, 0x00, 0x00}, S::Unsupported, R::UnsupportedValid);
    bad({0xCD, 0x80}, S::Unsupported, R::UnsupportedValid);
    bad({0x9B}, S::Unsupported, R::UnsupportedValid);
    bad({0x8C, 0xC8}, S::Unsupported, R::UnsupportedValid);
    bad({0x0F, 0xA0}, S::Unsupported, R::UnsupportedValid);
    bad({0x0F, 0xA4, 0xC0, 0x03}, S::Unsupported, R::UnsupportedValid);
    bad({0xD7}, S::Unsupported, R::UnsupportedValid);
    bad({0x0F, 0xB2, 0x00}, S::Unsupported, R::UnsupportedValid);
    bad({0x0F, 0xC7, 0x30}, S::Unsupported, R::UnsupportedValid);
    // 16-bit stack / branch operand sizes
    bad({0x66, 0xE8, 0x00, 0x01, 0x00, 0x00}, S::Unsupported, R::UnsupportedValid);
    bad({0x66, 0xE9, 0x00, 0x01, 0x00, 0x00}, S::Unsupported, R::UnsupportedValid);
    bad({0x66, 0xC3}, S::Unsupported, R::UnsupportedValid);
    bad({0x66, 0x50}, S::Unsupported, R::UnsupportedValid);
    bad({0x66, 0x9C}, S::Unsupported, R::UnsupportedValid);
    bad({0x66, 0x74, 0x01}, S::Unsupported, R::UnsupportedValid);
}

TEST(X64Decoder, BadPrefixes) {
    using S = x64::DecodeStatus;
    using R = x64::RejectClass;
    bad({0xF2, 0xC3}, S::Invalid, R::BadPrefix);
    bad({0xF2, 0x90}, S::Invalid, R::BadPrefix);
    bad({0xF3, 0x48, 0x01, 0xC1}, S::Invalid, R::BadPrefix);
    bad({0xF3, 0x0F, 0xA3, 0xC1}, S::Invalid, R::BadPrefix);
    bad({0xF2, 0xF3, 0x90}, S::Invalid, R::BadPrefix);
    bad({0xF0, 0x48, 0x01, 0xC0}, S::Invalid, R::BadPrefix);   // LOCK on a register op
    bad({0xF0, 0x90}, S::Invalid, R::BadPrefix);
    bad({0xF0, 0x48, 0x39, 0x01}, S::Invalid, R::BadPrefix);   // LOCK CMP: not permitted
    bad({0xF0, 0x48, 0x89, 0x01}, S::Invalid, R::BadPrefix);   // LOCK MOV
}

TEST(X64Decoder, TruncatedInstructions) {
    using S = x64::DecodeStatus;
    using R = x64::RejectClass;
    bad({}, S::Truncated, R::NeedMoreBytes);
    bad({0x48}, S::Truncated, R::NeedMoreBytes);
    bad({0x48, 0xB8, 1, 2}, S::Truncated, R::NeedMoreBytes);
    bad({0x48, 0x8B}, S::Truncated, R::NeedMoreBytes);
    bad({0x48, 0x8B, 0x44}, S::Truncated, R::NeedMoreBytes);
    bad({0x48, 0x8B, 0x84, 0x24}, S::Truncated, R::NeedMoreBytes);
    bad({0x0F}, S::Truncated, R::NeedMoreBytes);
    bad({0x0F, 0x84, 0x00}, S::Truncated, R::NeedMoreBytes);
    bad({0x66, 0x66}, S::Truncated, R::NeedMoreBytes);
    // a null buffer with a nonzero length is reported, never dereferenced
    const auto r = x64::decode(nullptr, 4, 0);
    EXPECT_EQ(r.status, x64::DecodeStatus::Truncated);
    // consumed is reported for a truncated instruction
    const auto t = bad({0x48, 0x8B, 0x44}, S::Truncated, R::NeedMoreBytes);
    EXPECT_EQ(t.consumed, 3);
}

TEST(X64Decoder, FifteenByteLimit) {
    using S = x64::DecodeStatus;
    using R = x64::RejectClass;
    // 5 x 66 + 48 B8 + imm64 = exactly 15 bytes: valid.
    const auto max = ok({0x66, 0x66, 0x66, 0x66, 0x66, 0x48, 0xB8, 1, 2, 3, 4, 5, 6, 7, 8});
    EXPECT_EQ(max.length, 15);
    EXPECT_EQ(max.op_size, 64);
    // 6 x 66 + 48 B8 + imm64 = 16 bytes: too long.
    bad({0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x48, 0xB8, 1, 2, 3, 4, 5, 6, 7, 8},
         S::Invalid, R::TooLong);
    // 14 prefixes + NOP: the opcode would be the 16th byte.
    bad({0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66,
         0x66, 0x66, 0x90}, S::Invalid, R::TooLong);
    // 13 prefixes + 48 B8 + imm64 = 23 bytes.
    bad({0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66,
         0x66, 0x48, 0xB8, 1, 2, 3, 4, 5, 6, 7, 8}, S::Invalid, R::TooLong);
    // 14 prefixes that end the buffer: truncated, not too long.
    bad({0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66, 0x66,
         0x66, 0x66}, S::Truncated, R::NeedMoreBytes);
}

// ── metadata ──────────────────────────────────────────────────────────────

TEST(X64Decoder, FlagsEffectTable) {
    std::uint64_t gprs[16] = {0};
    const auto eff = [&](std::initializer_list<int> b) {
        const auto d = ok(b);
        return x64::flags_effect(d, gprs);
    };
    EXPECT_EQ(eff({0x48, 0x01, 0xC0}).affected, kAll6);
    EXPECT_EQ(eff({0x48, 0x01, 0xC0}).defined, kAll6);
    EXPECT_EQ(eff({0x48, 0x31, 0xC0}).defined, kAll6 & ~x64::kRfAf);   // logic: AF undefined
    EXPECT_EQ(eff({0x48, 0xFF, 0xC0}).affected, kAll6 & ~x64::kRfCf);  // INC keeps CF
    EXPECT_EQ(eff({0x48, 0xF7, 0xE0}).defined, x64::kRfCf | x64::kRfOf);
    EXPECT_EQ(eff({0x48, 0xF7, 0xF0}).defined, 0u);                     // DIV: all undefined
    EXPECT_EQ(eff({0x48, 0x0F, 0xA3, 0xC1}).defined, x64::kRfCf);
    EXPECT_EQ(eff({0x48, 0x0F, 0xBC, 0xC1}).defined, x64::kRfZf);
    EXPECT_EQ(eff({0x48, 0x89, 0xC8}).affected, 0u);
    EXPECT_EQ(eff({0x48, 0x8D, 0x00}).affected, 0u);
    EXPECT_EQ(eff({0x48, 0x0F, 0x44, 0xC1}).affected, 0u);
    EXPECT_EQ(eff({0xFC}).defined, x64::kRfDf);
    EXPECT_EQ(eff({0xF5}).defined, x64::kRfCf);
    EXPECT_EQ(eff({0x9D}).defined, kAll6 | x64::kRfTf | x64::kRfDf);   // IF unchanged
    EXPECT_EQ(eff({0x9C}).affected, 0u);
    // shifts
    EXPECT_EQ(eff({0x48, 0xD1, 0xE0}).defined, kAll6 & ~x64::kRfAf);
    EXPECT_EQ(eff({0x48, 0xC1, 0xE0, 0x05}).defined,
              kAll6 & ~x64::kRfAf & ~x64::kRfOf);        // multi-bit: OF undefined
    EXPECT_EQ(eff({0x48, 0xC1, 0xE0, 0x00}).affected, 0u);  // count 0: nothing changes
    gprs[1] = 0;
    EXPECT_EQ(eff({0x48, 0xD3, 0xE0}).affected, 0u);
    gprs[1] = 32;
    EXPECT_EQ(eff({0x48, 0xD3, 0xE0}).defined, kAll6 & ~x64::kRfAf & ~x64::kRfOf);
    gprs[1] = 64;                                               // 64 & 63 == 0
    EXPECT_EQ(eff({0x48, 0xD3, 0xE0}).affected, 0u);
    gprs[1] = 0;
    // rotates
    EXPECT_EQ(eff({0x48, 0xD1, 0xC0}).defined, x64::kRfCf | x64::kRfOf);
    EXPECT_EQ(eff({0x48, 0xC1, 0xC0, 0x40}).affected, 0u);   // masked count 0
    EXPECT_EQ(eff({0x48, 0xC1, 0xC0, 0x03}).defined, x64::kRfCf);
    EXPECT_EQ(eff({0xC1, 0xC0, 0x08}).defined, x64::kRfCf);  // ROL eax, 8: CF defined
    EXPECT_EQ(eff({0xC0, 0xC0, 0x08}).defined, 0u);          // ROL al, 8: no rotation
    EXPECT_EQ(eff({0xC0, 0xC0, 0x09}).defined, x64::kRfCf);
    EXPECT_EQ(eff({0x48, 0xC1, 0xD0, 0x01}).defined, x64::kRfCf | x64::kRfOf);
    EXPECT_EQ(eff({0x48, 0xC1, 0xD0, 0x03}).defined, x64::kRfCf);
    EXPECT_EQ(eff({0xC0, 0xD0, 0x09}).defined, 0u);  // RCL al, 9: 9 % 9 == 0: no rotation
    EXPECT_EQ(eff({0xC0, 0xD0, 0x08}).defined, x64::kRfCf);  // one effective rotation
}

TEST(X64Decoder, ConditionEvaluation) {
    const std::uint64_t base = 0x202;   // bit1 + IF
    // O,NZ,NC,S,PF
    const std::uint64_t f = base | x64::kRfOf | x64::kRfSf | x64::kRfPf;
    EXPECT_TRUE(x64::condition_holds(0, f));    // O
    EXPECT_FALSE(x64::condition_holds(1, f));   // NO
    EXPECT_FALSE(x64::condition_holds(2, f));   // B
    EXPECT_TRUE(x64::condition_holds(3, f));    // AE
    EXPECT_FALSE(x64::condition_holds(4, f));   // E
    EXPECT_TRUE(x64::condition_holds(5, f));    // NE
    EXPECT_FALSE(x64::condition_holds(6, f));   // BE
    EXPECT_TRUE(x64::condition_holds(7, f));    // A
    EXPECT_TRUE(x64::condition_holds(8, f));    // S
    EXPECT_FALSE(x64::condition_holds(9, f));   // NS
    EXPECT_TRUE(x64::condition_holds(10, f));   // P
    EXPECT_FALSE(x64::condition_holds(11, f));  // NP
    EXPECT_FALSE(x64::condition_holds(12, f));  // L: SF != OF (both set)
    EXPECT_TRUE(x64::condition_holds(13, f));   // GE
    EXPECT_FALSE(x64::condition_holds(14, f));  // LE
    EXPECT_TRUE(x64::condition_holds(15, f));   // G
    // CF/ZF set
    const std::uint64_t g = base | x64::kRfCf | x64::kRfZf;
    EXPECT_TRUE(x64::condition_holds(2, g));
    EXPECT_FALSE(x64::condition_holds(3, g));
    EXPECT_TRUE(x64::condition_holds(4, g));
    EXPECT_FALSE(x64::condition_holds(5, g));
    EXPECT_TRUE(x64::condition_holds(6, g));
    EXPECT_FALSE(x64::condition_holds(7, g));
    EXPECT_TRUE(x64::condition_holds(14, g));   // LE: ZF
    EXPECT_FALSE(x64::condition_holds(15, g));
    EXPECT_FALSE(x64::condition_holds(12, g));  // L: SF == OF
    EXPECT_TRUE(x64::condition_holds(13, g));   // GE
    // SF != OF
    const std::uint64_t h = base | x64::kRfSf;
    EXPECT_TRUE(x64::condition_holds(12, h));
    EXPECT_FALSE(x64::condition_holds(13, h));
    EXPECT_TRUE(x64::condition_holds(14, h));
    EXPECT_FALSE(x64::condition_holds(15, h));
}

TEST(X64Decoder, MetadataNames) {
    EXPECT_STREQ(x64::status_name(x64::DecodeStatus::Ok), "ok");
    EXPECT_STREQ(x64::status_name(x64::DecodeStatus::Truncated), "truncated");
    EXPECT_STREQ(x64::status_name(x64::DecodeStatus::Invalid), "invalid");
    EXPECT_STREQ(x64::status_name(x64::DecodeStatus::Unsupported), "unsupported");
    EXPECT_STREQ(x64::reject_class_name(x64::RejectClass::UnsupportedSimd), "unsupported-simd");
    EXPECT_STREQ(x64::reject_class_name(x64::RejectClass::TooLong), "too-long");
    EXPECT_STREQ(x64::mnemonic_name(x64::Mnemonic::Movsxd), "movsxd");
    EXPECT_STREQ(x64::mnemonic_name(x64::Mnemonic::Invalid), "invalid");
    EXPECT_EQ(x64::instruction_group(x64::Mnemonic::Add), x64::Group::Alu);
    EXPECT_EQ(x64::instruction_group(x64::Mnemonic::Ret), x64::Group::ControlFlow);
    EXPECT_EQ(x64::instruction_group(x64::Mnemonic::Push), x64::Group::StackFlags);
    EXPECT_TRUE(x64::is_branch(x64::Mnemonic::Jcc));
    EXPECT_FALSE(x64::is_branch(x64::Mnemonic::Cmovcc));
    EXPECT_TRUE(x64::is_branch(x64::Mnemonic::Call));
    EXPECT_TRUE(x64::is_block_terminator(x64::Mnemonic::Jmp));
    EXPECT_FALSE(x64::is_block_terminator(x64::Mnemonic::Jcc));
    EXPECT_FALSE(x64::is_block_terminator(x64::Mnemonic::Call));
    EXPECT_TRUE(x64::is_call(x64::Mnemonic::Call));
    EXPECT_TRUE(x64::is_return(x64::Mnemonic::Ret));
    EXPECT_FALSE(x64::is_return(x64::Mnemonic::Leave));
}

TEST(X64Decoder, ValueHelpers) {
    EXPECT_EQ(x64::operand_size_mask(8), 0xFFu);
    EXPECT_EQ(x64::operand_size_mask(16), 0xFFFFu);
    EXPECT_EQ(x64::operand_size_mask(32), 0xFFFFFFFFu);
    EXPECT_EQ(x64::operand_size_mask(64), ~0ull);
    EXPECT_EQ(x64::sign_extend(0x80, 8), -128);
    EXPECT_EQ(x64::sign_extend(0x7F, 8), 127);
    EXPECT_EQ(x64::sign_extend(0xFFFFFFFFu, 32), -1);
    EXPECT_EQ(x64::sign_extend(0x8000000000000000ull, 64), INT64_MIN);
    EXPECT_EQ(x64::sign_extend(0x1234567812345678ull, 64), 0x1234567812345678ll);
}

TEST(X64Decoder, OpcodeSweepNeverInventsInstructions) {
    // The only bytes that are complete one-byte instructions. Every other byte
    // must decode to something longer, or to an explicit reject with a reason.
    const std::set<int> one_byte = {
        0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57,      // PUSH r
        0x58, 0x59, 0x5A, 0x5B, 0x5C, 0x5D, 0x5E, 0x5F,      // POP r
        0x90, 0x91, 0x92, 0x93, 0x94, 0x95, 0x96, 0x97,      // XCHG eAX, r
        0x98, 0x99, 0x9C, 0x9D, 0x9E, 0x9F, 0xCC, 0xC3, 0xC9,
        0xF5, 0xF8, 0xF9, 0xFC, 0xFD,
    };
    std::set<int> seen_one_byte;
    for (unsigned b = 0; b < 256; ++b) {
        std::uint8_t buf[16] = {};
        buf[0] = static_cast<std::uint8_t>(b);   // zero fill after the byte
        const auto r = x64::decode(buf, sizeof(buf), kRip);
        const auto lone = x64::decode(buf, 1, kRip);
        if (r.status != x64::DecodeStatus::Ok) {
            // 16 bytes are always enough: only an explicit reject is allowed.
            EXPECT_NE(r.status, x64::DecodeStatus::Truncated) << hex(bytes({static_cast<int>(b)}));
            EXPECT_NE(r.reject, x64::RejectClass::NeedMoreBytes);
            ASSERT_NE(r.reason, nullptr);
            EXPECT_NE(r.reason[0], '\0');
            continue;
        }
        EXPECT_GE(r.ins.length, 1u);
        EXPECT_LE(r.ins.length, 15u);
        EXPECT_NE(r.ins.mnem, x64::Mnemonic::Invalid);
        if (r.ins.length == 1) {
            EXPECT_TRUE(one_byte.count(static_cast<int>(b)) != 0)
                << "byte " << hex(bytes({static_cast<int>(b)})) << " decoded as a 1-byte "
                << x64::format_instruction(r.ins);
            seen_one_byte.insert(static_cast<int>(b));
            EXPECT_EQ(lone.status, x64::DecodeStatus::Ok);
            EXPECT_EQ(lone.ins.length, 1u);
        } else {
            EXPECT_EQ(lone.status, x64::DecodeStatus::Truncated);
            EXPECT_EQ(lone.reject, x64::RejectClass::NeedMoreBytes);
            EXPECT_EQ(lone.consumed, 1u);
        }
    }
    EXPECT_EQ(seen_one_byte, one_byte);
}

TEST(X64Decoder, EveryTruncationOfARealEncodingIsReported) {
    const std::vector<std::vector<std::uint8_t>> insns = {
        bytes({0x48, 0x8B, 0x84, 0x91, 0x78, 0x56, 0x34, 0x12}),   // mov rax,[rcx+rdx*4+disp32]
        bytes({0x48, 0xB8, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08}),
        bytes({0xE8, 0x01, 0x02, 0x03, 0x04}),                      // call rel32
        bytes({0x66, 0x0F, 0x1F, 0x84, 0x24, 0x00, 0x00, 0x00, 0x00}),   // 9-byte NOP
        bytes({0xF3, 0x0F, 0x1E, 0xFA}),                            // endbr64
        bytes({0x0F, 0x84, 0x01, 0x02, 0x03, 0x04}),                // je rel32
        bytes({0x48, 0x0F, 0xB6, 0x84, 0x08, 0x7F, 0x01, 0x00, 0x00}),   // movzx rax, byte [rax+rcx+0x17f]
        bytes({0x41, 0x0F, 0xB7, 0x84, 0xD5, 0x00, 0x01, 0x00, 0x00}),   // movzx eax, word [r13*8+rdx+0x100]
    };
    for (const auto& v : insns) {
        for (std::size_t n = 0; n < v.size(); ++n) {
            const auto r = x64::decode(v.data(), n, kRip);
            ASSERT_EQ(r.status, x64::DecodeStatus::Truncated) << hex(v) << " cut at " << n;
            EXPECT_EQ(r.reject, x64::RejectClass::NeedMoreBytes);
            EXPECT_LE(r.consumed, n);      // never past the buffer
            EXPECT_EQ(r.ins.length, 0u);
        }
        const auto full = x64::decode(v.data(), v.size(), kRip);
        ASSERT_EQ(full.status, x64::DecodeStatus::Ok) << hex(v) << ": " << full.reason;
        EXPECT_EQ(full.ins.length, v.size());
    }
    // A null buffer or a zero-length buffer is truncated, never Ok.
    EXPECT_EQ(x64::decode(nullptr, 0, kRip).status, x64::DecodeStatus::Truncated);
    EXPECT_EQ(x64::decode(nullptr, 8, kRip).status, x64::DecodeStatus::Truncated);
}

